function setTerraceGlass(active,floor){
  for(const deck of floor.children){
    if(!deck.userData.roseDeck)continue;
    deck.traverse(node=>{
      const mat=node.material;
      if(!mat||Array.isArray(mat))return;
      let record=mat.userData.terraceOriginal;
      if(!record&&active){
        let type='';
        if(mat.isMeshBasicMaterial&&mat.vertexColors&&mat.side===THREE.DoubleSide&&mat.opacity===.57)type='glass';
        else if(mat.isMeshStandardMaterial&&mat.customProgramCacheKey()==='hayden-metal-panels-v2')type='aluminum';
        if(!type)return;
        record={type,color:mat.color.clone(),opacity:mat.opacity,metalness:mat.metalness,roughness:mat.roughness};
        mat.userData.terraceOriginal=record;
      }
      if(!record)return;
      if(!active){
        mat.color.copy(record.color);mat.opacity=record.opacity;
        if(record.type==='aluminum'){mat.metalness=record.metalness;mat.roughness=record.roughness;}
        return;
      }
      if(record.type==='glass'){mat.color.set(0x94b8c5);mat.opacity=.145;}
      else{mat.color.set(0xcfdbdd);mat.metalness=.55;mat.roughness=.43;}
    });
  }
}
